// Move both image panels to the very top of #b_results
const imagesOfCats = element.querySelector('li.b_ans.b_imgansacf');
const aside = document.querySelector('aside[aria-label="Additional Results"]');
const explorePanel = aside ? aside.querySelector('li.b_ans.b_imgexpansacf') : null;

if (imagesOfCats && element.children[0] !== imagesOfCats) {
  element.insertBefore(imagesOfCats, element.firstChild);
}

// Clone the "Explore with images" panel into b_results right after "Images of Cats"
const existingClone = element.querySelector('li.b_imgexpansacf-clone');
if (explorePanel && !existingClone) {
  const clone = explorePanel.cloneNode(true);
  clone.classList.add('b_imgexpansacf-clone');
  clone.style.display = 'block';
  // Insert after imagesOfCats
  if (imagesOfCats && imagesOfCats.nextSibling) {
    element.insertBefore(clone, imagesOfCats.nextSibling);
  } else {
    element.appendChild(clone);
  }
  // Hide the original aside panel to avoid duplication
  if (aside) aside.style.display = 'none';
}

// Scale up all image items within the masonry plan — double the height
const items = element.querySelectorAll('.iacfmit');
const currentHeight = parseInt(element.style.height, 10);
if (currentHeight && !element.dataset.enlarged) {
  element.style.height = (currentHeight * 1.8) + 'px';
  element.dataset.enlarged = '1';
  items.forEach(item => {
    const top = parseFloat(item.style.top);
    const height = parseFloat(item.style.height);
    const left = item.style.left;
    const width = item.style.width;
    if (!item.dataset.enlarged) {
      item.style.height = (height * 1.8) + 'px';
      if (top > 0) item.style.top = (top * 1.8) + 'px';
      item.dataset.enlarged = '1';
    }
  });
}

